import{_ as n,y as i,a as g,o as l,g as t,D as a,a2 as s,I as o}from"./chunks/framework.DCcmcJcL.js";const b=JSON.parse('{"title":"Categories","description":"","frontmatter":{},"headers":[],"relativePath":"category/create-category.md","filePath":"category/create-category.md","lastUpdated":1789441803000}'),h={name:"category/create-category.md"};function d(c,e,u,p,y,m){const r=i("ImagePopup");return l(),g("div",null,[e[6]||(e[6]=t("h1",{id:"categories",tabindex:"-1"},[o("Categories "),t("a",{class:"header-anchor",href:"#categories","aria-label":'Permalink to "Categories"'},"​")],-1)),e[7]||(e[7]=t("p",null,"Categories organize your catalog. They make up the storefront menu, and each category has a page where shoppers browse and filter its products. Categories form a tree: each channel has a root category, and the categories under it are the ones that channel's storefront shows.",-1)),e[8]||(e[8]=t("h2",{id:"the-categories-list",tabindex:"-1"},[o("The categories list "),t("a",{class:"header-anchor",href:"#the-categories-list","aria-label":'Permalink to "The categories list"'},"​")],-1)),e[9]||(e[9]=t("p",null,[o("Go to "),t("strong",null,"Catalog >> Categories"),o(".")],-1)),a(r,{src:"/images/category/category-grid.png",alt:"Categories list under Catalog >> Categories"}),e[10]||(e[10]=s('<p>Each row shows the category&#39;s <strong>ID</strong>, <strong>Name</strong>, <strong>Parent Category</strong>, <strong>Position</strong> and <strong>Visible In Menu</strong>, which reads <strong>Active</strong> or <strong>Inactive</strong>. Names are shown in the admin panel&#39;s language, and a category without a name in that language isn&#39;t listed.</p><ul><li><strong>Search:</strong> type in the search box to find categories by their name or their parent&#39;s name.</li><li><strong>Filter:</strong> click <strong>Filter</strong> to filter by any column. <strong>Parent Category</strong> offers a list of the categories that have subcategories, and <strong>Visible In Menu</strong> offers <strong>Active</strong> and <strong>Inactive</strong>.</li><li><strong>Sort:</strong> click a column in the header row.</li><li><strong>Edit</strong> (the pencil) opens the category, and <strong>Delete</strong> (the bin) deletes it. See <a href="#delete-a-category">Delete a category</a>.</li></ul><h3 id="change-several-categories-at-once" tabindex="-1">Change several categories at once <a class="header-anchor" href="#change-several-categories-at-once" aria-label="Permalink to &quot;Change several categories at once&quot;">​</a></h3><ol><li>Go to <strong>Catalog &gt;&gt; Categories</strong>.</li><li>Tick the categories.</li><li>Open <strong>Select Action</strong>.</li><li>Choose <strong>Delete</strong>, or point to <strong>Update Status</strong> and choose <strong>Active</strong> or <strong>Inactive</strong>.</li></ol>',4)),a(r,{src:"/images/category/category-mass-actions.png",alt:"Select Action menu with Delete and Update Status for two ticked categories"}),e[11]||(e[11]=s('<p><strong>Update Status</strong> switches <strong>Visible In Menu</strong> on or off for every ticked category.</p><p>If the ticked categories include a root category, deleting stops there and <strong>The Root category can not be deleted.</strong> appears. Categories deleted before it stay deleted.</p><h2 id="root-categories-and-the-storefront-menu" tabindex="-1">Root categories and the storefront menu <a class="header-anchor" href="#root-categories-and-the-storefront-menu" aria-label="Permalink to &quot;Root categories and the storefront menu&quot;">​</a></h2><p>Every store starts with a root category called <strong>Root</strong>. A root category holds the categories of a storefront, and it isn&#39;t shown in the menu itself.</p><ul><li>Each channel has a <strong>Root Category</strong>, chosen under <strong>Settings &gt;&gt; Channels</strong>. See <a href="./../settings/channels.html">Channels</a>.</li><li>A channel&#39;s storefront menu shows the subcategories of its root category that are visible in the menu, with their own subcategories under them.</li><li><strong>Position</strong> sets the order of categories in the menu, lowest first.</li><li>A category&#39;s page opens only in the channels whose root category it sits under.</li><li>To create a root category for a new channel, create a category without a parent.</li></ul><p>Whether the storefront header lists the categories in a menu or in a sidebar is set in <a href="./../configure/design.html#menu-category-view">Design</a>.</p><h2 id="create-a-category" tabindex="-1">Create a category <a class="header-anchor" href="#create-a-category" aria-label="Permalink to &quot;Create a category&quot;">​</a></h2>',7)),t("ol",null,[e[3]||(e[3]=s("<li><p>Go to <strong>Catalog &gt;&gt; Categories</strong>.</p></li><li><p>Click <strong>Create Category</strong>. The <strong>Add New Category</strong> page opens.</p></li><li><p>In <strong>General</strong>, enter the <strong>Name</strong>. The <strong>Slug</strong> is filled in from the name as you type.</p></li><li><p>Under <strong>Parent Category</strong>, click the category the new one sits under, such as your channel&#39;s root category for a top-level menu item.</p></li><li><p>In <strong>Settings</strong>, enter the <strong>Position</strong>.</p></li><li><p>Choose the <strong>Display Mode</strong>.</p></li><li><p>Switch <strong>Visible In Menu</strong> on.</p></li>",7)),t("li",null,[e[0]||(e[0]=t("p",null,[o("In "),t("strong",null,"Filterable Attributes"),o(", tick the filters shoppers can use on the category page.")],-1)),a(r,{src:"/images/category/create-category-general.png",alt:"Add New Category page with the General, Settings and Filterable Attributes sections filled in for Garden & Outdoor"})]),e[4]||(e[4]=t("li",null,[t("p",null,[o("In "),t("strong",null,"Description and Images"),o(", enter the "),t("strong",null,"Description"),o(".")])],-1)),t("li",null,[e[1]||(e[1]=t("p",null,[o("Under "),t("strong",null,"Logo"),o(" and "),t("strong",null,"Banner"),o(", click "),t("strong",null,"Add Image"),o(" to upload the images.")],-1)),a(r,{src:"/images/category/create-category-description-images.png",alt:"Description and Images section with the description editor and the Logo and Banner uploaders"})]),t("li",null,[e[2]||(e[2]=t("p",null,[o("Fill in the "),t("strong",null,"SEO Details"),o(". See "),t("a",{href:"#seo-details"},"SEO Details"),o(".")],-1)),a(r,{src:"/images/category/create-category-seo.png",alt:"SEO Details section with a search result preview, meta title, slug, keywords and description"})]),e[5]||(e[5]=t("li",null,[t("p",null,[o("Click "),t("strong",null,"Save Category"),o(". The category is created and the categories list opens.")])],-1))]),e[12]||(e[12]=s('<p>The name, description and SEO details you enter are used for every language until you translate them. See <a href="#edit-or-translate-a-category">Edit or translate a category</a>. To put products in the category, tick it in the <strong>Categories</strong> section of the product edit screen. See <a href="./../product-types/products.html#categories">Products</a>.</p><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong>Name:</strong> the name shoppers see in the menu and on the category page.</li><li><strong>Parent Category:</strong> the category this one sits under. Click the arrow next to a category to show or hide its subcategories. Don&#39;t choose a parent to create a root category.</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li><strong>Position:</strong> the category&#39;s place among the categories next to it in the menu, lowest first. Enter a whole number.</li><li><strong>Display Mode:</strong> what the category page shows.</li><li><strong>Visible In Menu:</strong> shows the category in the storefront menu. See <a href="#hide-a-category-from-the-menu">Hide a category from the menu</a>.</li></ul><table tabindex="0"><thead><tr><th>Display Mode</th><th>The category page shows</th></tr></thead><tbody><tr><td><strong>Products and Description</strong></td><td>The description, then the products with their filters. This is the default.</td></tr><tr><td><strong>Products Only</strong></td><td>The products with their filters, without the description.</td></tr><tr><td><strong>Description Only</strong></td><td>The description, without products.</td></tr></tbody></table><p>The banner shows at the top of the page in every mode. The <strong>Description</strong> is required unless the mode is <strong>Products Only</strong>.</p>',7)),a(r,{src:"/images/category/storefront-category-page.png",alt:"Household category page on the storefront with its description, filters and products"}),e[13]||(e[13]=s('<h3 id="filterable-attributes" tabindex="-1">Filterable Attributes <a class="header-anchor" href="#filterable-attributes" aria-label="Permalink to &quot;Filterable Attributes&quot;">​</a></h3><p>The list shows every attribute with <strong>Use in Layered Navigation</strong> switched on, such as <strong>Price</strong>, <strong>Color</strong>, <strong>Size</strong> and <strong>Brand</strong>. Tick at least one. The ticked attributes become the filters on the category page: <strong>Price</strong> shows as a range slider, and the others as checkboxes. To add an attribute to the list, switch on <strong>Use in Layered Navigation</strong> in its <a href="./../attribute/product-attribute.html#configuration">configuration</a>.</p><h3 id="description-and-images" tabindex="-1">Description and Images <a class="header-anchor" href="#description-and-images" aria-label="Permalink to &quot;Description and Images&quot;">​</a></h3><ul><li><strong>Description:</strong> the text at the top of the category page, written in a text editor.</li><li><strong>Logo:</strong> the category&#39;s small image. A resolution of 110 × 110 pixels is recommended.</li><li><strong>Banner:</strong> the wide image at the top of the category page. A size of 1320 × 300 pixels is recommended.</li></ul><p>Upload images in PNG, JPEG, JPG, BMP or WEBP format. To add alt text or rename an image&#39;s file, point to the uploaded image and click the pencil icon.</p><h3 id="generative-ai-magic-ai" tabindex="-1">Generative AI (Magic AI) <a class="header-anchor" href="#generative-ai-magic-ai" aria-label="Permalink to &quot;Generative AI (Magic AI)&quot;">​</a></h3><p>When Generative AI (Magic AI) is set up:</p><ul><li>the <strong>Magic AI</strong> button in the <strong>Description</strong> editor writes the description for you. It stays greyed out until text generation is switched on. See <a href="./../generative-ai/generate-content.html">Generate Text Content</a>.</li><li>a <strong>Magic AI</strong> button next to <strong>Add Image</strong> under <strong>Logo</strong> and <strong>Banner</strong> creates the image from a description. It appears when image generation is switched on and no image has been uploaded yet. See <a href="./../generative-ai/generate-images.html">Generate Product Images</a>.</li></ul><h3 id="seo-details" tabindex="-1">SEO Details <a class="header-anchor" href="#seo-details" aria-label="Permalink to &quot;SEO Details&quot;">​</a></h3><p>The preview at the top shows how the category could appear in search results, and it updates as you type.</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Meta Title</strong></td><td>The title in search results and the browser tab. When it&#39;s empty, the category name is used.</td></tr><tr><td><strong>Slug</strong></td><td>The last part of the category page&#39;s address, such as <code>garden-outdoor</code>. It&#39;s filled in from the name. Use letters, numbers and hyphens. It must differ from every other category&#39;s slug and every product&#39;s URL key, and <code>categories</code> can&#39;t be used.</td></tr><tr><td><strong>Meta Keywords</strong></td><td>Words and phrases the category should be found by.</td></tr><tr><td><strong>Meta Description</strong></td><td>The summary in search results. When it&#39;s empty, the start of the description is used.</td></tr></tbody></table><h2 id="edit-or-translate-a-category" tabindex="-1">Edit or translate a category <a class="header-anchor" href="#edit-or-translate-a-category" aria-label="Permalink to &quot;Edit or translate a category&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Categories</strong>.</li><li>Click <strong>Edit</strong> on the category&#39;s row. The <strong>Edit Category</strong> page opens.</li><li>Choose the language in the language selector below the title.</li><li>Change the fields.</li><li>Click <strong>Save Category</strong>.</li></ol>',13)),a(r,{src:"/images/category/edit-category.png",alt:"Edit Category page for Household with the language selector set to English"}),e[14]||(e[14]=s('<p>The language selector appears when your store has more than one language. These fields are saved separately for each language: <strong>Name</strong>, <strong>Description</strong>, <strong>Meta Title</strong>, <strong>Slug</strong>, <strong>Meta Keywords</strong>, <strong>Meta Description</strong>, and the alt text of the logo and banner. The other fields, such as <strong>Select Parent Category</strong>, the images, <strong>Position</strong>, <strong>Display Mode</strong>, <strong>Visible In Menu</strong> and <strong>Filterable Attributes</strong>, are the same in every language.</p><p>There&#39;s no channel selector: categories are shared by all channels, and each channel shows the categories under its root category. Under <strong>Select Parent Category</strong>, the tree leaves out the category itself and its subcategories.</p><div class="warning custom-block"><p class="custom-block-title">Renaming changes the address</p><p>When you change the <strong>Name</strong>, the <strong>Slug</strong> is rewritten from the new name, which changes the address of the category page in that language. Bagisto adds a <a href="./../marketing/url-rewrite.html">URL rewrite</a> that sends visitors from the old address to the new one. To keep the old address, type the old slug back before you save.</p></div><h3 id="hide-a-category-from-the-menu" tabindex="-1">Hide a category from the menu <a class="header-anchor" href="#hide-a-category-from-the-menu" aria-label="Permalink to &quot;Hide a category from the menu&quot;">​</a></h3><p>Switch <strong>Visible In Menu</strong> off to take a category and its subcategories out of the storefront menu. The category page still opens from a direct link or a bookmark. While it&#39;s off, the category isn&#39;t offered in the <strong>Categories</strong> section of the product edit screen.</p><h2 id="delete-a-category" tabindex="-1">Delete a category <a class="header-anchor" href="#delete-a-category" aria-label="Permalink to &quot;Delete a category&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Categories</strong>.</li><li>Click <strong>Delete</strong> on the category&#39;s row.</li><li>Confirm the deletion.</li></ol><div class="warning custom-block"><p class="custom-block-title">Subcategories are deleted too</p><p>Deleting a category also deletes all of its subcategories, and it can&#39;t be undone. The products in them aren&#39;t deleted, but they&#39;re no longer in those categories.</p></div><p>The <strong>Root</strong> category that comes with your store can&#39;t be deleted, and neither can a category chosen as a channel&#39;s <strong>Root Category</strong>: <strong>The Root category can not be deleted.</strong> appears. To delete a channel&#39;s root category, choose another root category for the channel first.</p>',9))])}const w=n(h,[["render",d]]);export{b as __pageData,w as default};
